use chrono::{DateTime, Utc};
use diesel::prelude::*;
use uuid::Uuid;

// Generated by `diesel print-schema` from the `payment_method` Postgres enum,
// so it always matches the database.
pub use crate::schema::rust_types::PaymentMethod;

#[derive(Queryable, Selectable, Identifiable, Debug)]
#[diesel(table_name = crate::schema::term_payments)]
#[diesel(check_for_backend(diesel::pg::Pg))]
pub struct TermPayment {
	id: Uuid,
	net_id: String,
	time_purchased: DateTime<Utc>,
	amount_paid_cents: i32,
	method: PaymentMethod,
	metadata: serde_json::Value,
}
